import{_ as e}from"./chunks/X25-EVO.BLINERX1.js";import{_ as a,c as r,o as i,al as l}from"./chunks/framework.CT7RwC5a.js";const b=JSON.parse('{"title":"CUAV X25-EVO","description":"","frontmatter":{},"headers":[],"relativePath":"ko/flight_controller/cuav_x25-evo.md","filePath":"ko/flight_controller/cuav_x25-evo.md"}'),o={name:"ko/flight_controller/cuav_x25-evo.md"};function n(s,t,d,u,h,c){return i(),r("div",null,t[0]||(t[0]=[l('<h1 id="cuav-x25-evo" tabindex="-1">CUAV X25-EVO <a class="header-anchor" href="#cuav-x25-evo" aria-label="Permalink to &quot;CUAV X25-EVO&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>PX4 does not manufacture this (or any) autopilot. Contact the <a href="https://store.cuav.net/" target="_blank" rel="noreferrer">manufacturer</a> for hardware support or compliance issues.</p></div><p>The <em>X25-EVO</em> is an advanced autopilot manufactured by CUAV<sup>®</sup>.</p><p>The autopilot is recommended for commercial system integration but is also suitable for academic research and any other applications.</p><p><img src="'+e+'" alt="X25-EVO AutoPilot - hero image"></p><p>The X25-EVO brings you ultimate performance, stability, and reliability in every aspect.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>이 비행 컨트롤러는 <a href="./../flight_controller/autopilot_manufacturer_supported.html">제조업체에서 지원</a>합니다.</p></div><h3 id="특징" tabindex="-1">특징 <a class="header-anchor" href="#특징" aria-label="Permalink to &quot;특징&quot;">​</a></h3><ul><li>Arm® Cortex-M7® processor (STM32H743XI) with Floating-Point Unit (FPU), operating at 480MHz, and featuring 2MB Flash memory. Enables developers to enhance productivity and efficiency, allowing for more complex algorithms and models.</li><li>Automotive-grade RM3100 compass. Designed for better stability and anti-interference capability.</li><li>Triple-redundant IMUs and dual-redundant barometers located on separate buses. If the PX4 autopilot detects a sensor failure, the system seamlessly switches to another sensor to maintain flight control reliability.</li><li>Independent LDO power control supplies power to each sensor group. A vibration isolation system filters high-frequency vibrations and reduces noise to ensure accurate readings, enabling better overall flight performance for the vehicle.</li><li>Integrated Microchip Ethernet PHY for high-speed communication with onboard devices like mission computers via Ethernet.</li><li>Dual temperature compensation systems, located on the IMU board and FMU board respectively. Temperature is controlled by onboard heating resistors to achieve the optimal operating temperature for the IMUs.</li><li>PWM servo output voltage switchable between 3.3V or 5V.</li><li>Modular design for DIY carrier boards.</li></ul><h3 id="processors-sensors" tabindex="-1">Processors &amp; Sensors <a class="header-anchor" href="#processors-sensors" aria-label="Permalink to &quot;Processors &amp; Sensors&quot;">​</a></h3><ul><li>Main Processor: STM32H743XI <ul><li>32-bit Arm® Cortex®-M7, 480MHz, 2MB Flash, 1MB RAM</li></ul></li><li>Onboard Sensors: <ul><li>Accel/Gyro: IIM42652*2</li><li>Accel/Gyro: IIM42653</li><li>자력계 : RM3100</li><li>Barometer: BMP581</li><li>Barometer: ICP-20100</li></ul></li></ul><h3 id="전기-데이터" tabindex="-1">전기 데이터 <a class="header-anchor" href="#전기-데이터" aria-label="Permalink to &quot;전기 데이터&quot;">​</a></h3><ul><li>Rated Voltage: <ul><li>Input Voltage: 10~18V</li><li>USB 전원 입력: 4.75~5.25V</li><li>Servo Rail Input: 0~9.9V</li></ul></li><li>Rated Current: <ul><li>Total Output Max Current: 10A</li><li>TELEM1 and TELEM2 Output Current limiter: 4A</li><li>CAN1 and CAN2 Output Current limiter: 2.4A</li><li>Other Ports Output Current limiter: 1.5A</li></ul></li></ul><h3 id="인터페이스" tabindex="-1">인터페이스 <a class="header-anchor" href="#인터페이스" aria-label="Permalink to &quot;인터페이스&quot;">​</a></h3><ul><li>16x PWM Servo Outputs</li><li>1x Dedicated R/C Input for Spektrum / DSM and S.Bus</li><li>1x Analog/PWM RSSI Input</li><li>2x TELEM Ports (with full flow control)</li><li>1x UART4 Port</li><li>2x GPS Ports <ul><li>1x Full GPS plus Safety Switch Port (GPS1)</li><li>1x Basic GPS Port (with I2C, GPS2)</li></ul></li><li>1x USB Port (TYPE-C)</li><li>1x Ethernet Port <ul><li>Transformerless application</li><li>100Mbps</li></ul></li><li>3x I2C Bus Ports</li><li>1x SPI Bus <ul><li>1x Chip Select Line</li><li>1x Data Ready Line</li><li>1x SPI Reset Line</li></ul></li><li>5x CAN Ports for CAN Peripherals <ul><li>3x CAN1 Bus Multiplexed Ports</li><li>2x CAN2 Bus Multiplexed Ports</li></ul></li><li>2x Power Input Ports <ul><li>DroneCAN/UAVCAN Power Input</li></ul></li><li>2x AD Ports <ul><li>Analog Input (3.3V)</li><li>Analog Input (6.6V - not supported by PX4)</li></ul></li><li>1x Dedicated Debug Port <ul><li>FMU Debug</li></ul></li></ul><h3 id="기계식-부품" tabindex="-1">기계식 부품 <a class="header-anchor" href="#기계식-부품" aria-label="Permalink to &quot;기계식 부품&quot;">​</a></h3><ul><li>Not provided.</li></ul><h2 id="purchase-channels" tabindex="-1">Purchase Channels <a class="header-anchor" href="#purchase-channels" aria-label="Permalink to &quot;Purchase Channels&quot;">​</a></h2><p>Order from <a href="https://store.cuav.net/" target="_blank" rel="noreferrer">CUAV</a>.</p><h2 id="조립-및-설정" tabindex="-1">조립 및 설정 <a class="header-anchor" href="#조립-및-설정" aria-label="Permalink to &quot;조립 및 설정&quot;">​</a></h2><ul><li>Not provided.</li></ul><h2 id="pin-definitions" tabindex="-1">Pin Definitions <a class="header-anchor" href="#pin-definitions" aria-label="Permalink to &quot;Pin Definitions&quot;">​</a></h2><ul><li>Not provided.</li></ul><h2 id="시리얼-포트-매핑" tabindex="-1">시리얼 포트 매핑 <a class="header-anchor" href="#시리얼-포트-매핑" aria-label="Permalink to &quot;시리얼 포트 매핑&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UART</th><th>장치</th><th>포트</th></tr></thead><tbody><tr><td>USART1</td><td>/dev/ttyS0</td><td>GPS1</td></tr><tr><td>USART2</td><td>/dev/ttyS1</td><td>GPS2</td></tr><tr><td>USART3</td><td>/dev/ttyS2</td><td>디버그 콘솔</td></tr><tr><td>UART4</td><td>/dev/ttyS3</td><td>UART4</td></tr><tr><td>UART5</td><td>/dev/ttyS4</td><td>TELEM2</td></tr><tr><td>USART6</td><td>/dev/ttyS5</td><td>RC</td></tr><tr><td>UART7</td><td>/dev/ttyS6</td><td>TELEM1</td></tr></tbody></table><h2 id="정격-전압" tabindex="-1">정격 전압 <a class="header-anchor" href="#정격-전압" aria-label="Permalink to &quot;정격 전압&quot;">​</a></h2><p>The <em>X25-EVO</em> achieves triple redundancy on power supplies if three power sources are provided. The three power rails are POWERC1, POWERC2, and USB.</p><ul><li><strong>POWER C1</strong> and <strong>POWER C2</strong> are DroneCAN/UAVCAN battery interfaces.</li></ul><p><strong>Normal Operation Maximum Ratings</strong></p><p>Under these conditions, all power sources will be used to power the system in the following order:</p><ol><li><strong>POWER C1</strong> and <strong>POWER C2</strong> Inputs (10V to 18V)</li><li>USB Input (4.75V to 5.25V)</li></ol><p><strong>Voltage monitoring</strong></p><p>Digital DroneCAN/UAVCAN battery monitoring is enabled by default.</p><h2 id="펌웨어-빌드" tabindex="-1">펌웨어 빌드 <a class="header-anchor" href="#펌웨어-빌드" aria-label="Permalink to &quot;펌웨어 빌드&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Most users do not need to build this firmware! It is pre-built and installed automatically by <em>QGroundControl</em> when the appropriate hardware is connected.</p></div><p>To <a href="./../dev_setup/building_px4.html">build PX4</a> for this target, execute:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make cuav_x25-evo_default</span></span></code></pre></div><p><a id="debug_port"></a></p><h2 id="디버그-포트" tabindex="-1">디버그 포트 <a class="header-anchor" href="#디버그-포트" aria-label="Permalink to &quot;디버그 포트&quot;">​</a></h2><p>The <a href="./../debug/system_console.html">PX4 System Console</a> and <a href="./../debug/swd_debug.html">SWD Interface</a> operate on the <strong>FMU Debug</strong> port.</p><table tabindex="0"><thead><tr><th>핀</th><th>신호</th><th>전압</th></tr></thead><tbody><tr><td>1(red)</td><td>5V+</td><td>+5V</td></tr><tr><td>2 (흑)</td><td>DEBUG TX(출력)</td><td>+3.3V</td></tr><tr><td>3 (흑)</td><td>DEBUG TX(입력)</td><td>+3.3V</td></tr><tr><td>4 (흑)</td><td>FMU_SWDIO</td><td>+3.3V</td></tr><tr><td>5 (흑)</td><td>FMU_SWCLK</td><td>+3.3V</td></tr><tr><td>6 (흑)</td><td>GND</td><td>GND</td></tr></tbody></table><h2 id="지원-플랫폼-및-기체" tabindex="-1">지원 플랫폼 및 기체 <a class="header-anchor" href="#지원-플랫폼-및-기체" aria-label="Permalink to &quot;지원 플랫폼 및 기체&quot;">​</a></h2><p>Any multirotor/airplane/rover or boat that can be controlled using normal RC servos or Futaba S-Bus servos. The complete set of supported configurations can be found in the <a href="./../airframes/airframe_reference.html">Airframe Reference</a>.</p><h2 id="추가-정보" tabindex="-1">추가 정보 <a class="header-anchor" href="#추가-정보" aria-label="Permalink to &quot;추가 정보&quot;">​</a></h2><ul><li><a href="https://doc.cuav.net/" target="_blank" rel="noreferrer">CUAV Docs</a></li></ul>',45)]))}const f=a(o,[["render",n]]);export{b as __pageData,f as default};
